import React, { useState } from 'react';
import { loginUser } from '../services/api';
import { useNavigate } from 'react-router-dom';

function LoginPage({ onLogin }) {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const navigate = useNavigate();

    const handleLogin = async (e) => {
        e.preventDefault();
        console.log('Form submitted!');
        console.log('Email:', email);
        console.log('Password:', password);

        try {
            const userData = await loginUser(email, password); // Backend call
            console.log('Login successful! User data received:', userData);

            // Store token in localStorage
            localStorage.setItem('token', userData.token);
            console.log('Token stored in localStorage.');

            // Call the onLogin function passed as a prop
            onLogin(userData);

            // Redirect to home page
            navigate('/');
            console.log('Redirected to home page.');
        } catch (err) {
            console.error('Login error:', err.response || err);
            setError(err.response?.data?.message || 'Invalid email or password.');
        }
    };

    return (
        <div className="flex items-center justify-center h-screen bg-gray-100">
            <div className="bg-white p-6 rounded-lg shadow-md w-96">
                <h2 className="text-2xl font-bold text-center mb-4">Login</h2>
                <form onSubmit={handleLogin} className="space-y-4">
                    <input
                        type="email"
                        placeholder="Email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        className="block w-full p-3 border rounded"
                        required
                    />
                    <input
                        type="password"
                        placeholder="Password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        className="block w-full p-3 border rounded"
                        required
                    />
                    <button
                        type="submit"
                        className="w-full bg-blue-600 text-white py-2 px-4 rounded hover:bg-blue-500"
                    >
                        Login
                    </button>
                </form>
                {error && <p className="text-red-500 text-center mt-4">{error}</p>}
            </div>
        </div>
    );
}

// Default prop for onLogin
LoginPage.defaultProps = {
    onLogin: () => { }, // No-op if not provided
};

export default LoginPage;
